[exhibition] {
  "core_planning_data": {
    "standard_compliance": {
      "mandatory_zones": "常设展厅、短期展厅、报告厅、影像厅、科普活动室、适于学龄前儿童的展品而设置的展厅",
      "area_ratios": "[无具体证据]",
      "spatial_requirements": "同一时间展厅单位面积合理接待观众的最高数量为0.20人/m²~0.25人/m²（部分管理人员建议以0.30人/m²为最高限额）；展品所占面积平均值为23.1m²/件"
    },
    "baseline_themes": [
      {
        "theme_name": "展览教育用房",
        "typical_ratio": "[无具体证据]",
        "description": "主要包括：常设展厅、短期展厅、报告厅、影像厅、科普活动室等。",
        "reference": "科学技术馆建设标准"
      },
      {
        "theme_name": "学龄前儿童展厅",
        "typical_ratio": "[无具体证据]",
        "description": "为展示适于学龄前儿童的展品而设置的展厅。",
        "reference": "博物馆建筑设计规范"
      }
    ]
  },
  "trend_analysis_data": {
    "global_trends": [
      {
        "trend_name": "常设与临时展览体系的并重",
        "description": "现代科技馆倾向于同时规划常设展厅与临时展厅，以兼顾核心科普内容的稳定性与前沿话题的时效性，确保场馆内容的持续活力。",
        "evidence_cases": [
          {
            "case_name": "Museum of Medical History and Innovation",
            "snippet": "核心展厅与更替展厅 (core and changing exhibition galleries)"
          },
          {
            "case_name": "Shenzhen Science and Technology Museum",
            "snippet": "35,000平方米的常设和临时展厅及画廊 (35,000 sqm of permanent and temporary exhibition halls and galleries)"
          }
        ],
        "is_general_knowledge": false
      },
      {
        "trend_name": "基于中庭的立体化空间布局与导览",
        "description": "利用中庭作为核心枢纽，通过悬浮、辐射等布局方式连接各展厅，并利用空间视觉线索实现直观的参观导引，增强空间的连通性。",
        "evidence_cases": [
          {
            "case_name": "New Science and Technology Museum of Henan Province",
            "snippet": "近20个大型展厅围绕‘自然、天文和智能’主题，从中庭的三翼呈辐射状分布 (Nearly 20 large exhibition halls themed around 'Nature, Astronomy, and Intelligence' radiating from the atrium's three wings)"
          },
          {
            "case_name": "Shenzhen Science and Technology Museum",
            "snippet": "许多展厅从中庭的地面和墙壁中延伸出来……每一个都提供视觉线索，直观地引导参观者穿过博物馆一系列相互连接的空间 (The many galleries emerge from the floor and walls of its central atrium... each giving visual clues that intuitively direct visitors through the museum's series of interconnected spaces)"
          }
        ],
        "is_general_knowledge": false
      },
      {
        "trend_name": "观展体验中的休憩与沉思空间融合",
        "description": "在连续的观展流线中嵌入休息区或露台，为参观者提供缓解疲劳、欣赏景观及沉思消化的空间，提升整体参观体验的舒适度。",
        "evidence_cases": [
          {
            "case_name": "Yibin Science and Technology Museum",
            "snippet": "进入二楼展厅，那里拥有良好的视野并可供休息 (enter the second-floor exhibition hall, where you can have a good view and rest)"
          },
          {
            "case_name": "Shenzhen Science and Technology Museum",
            "snippet": "露台为探索展览时的休息和沉思提供了场所 (Terraces provide places for rest and contemplation while exploring the exhibitions)"
          }
        ],
        "is_general_knowledge": false
      },
      {
        "trend_name": "多学科主题的综合化集聚",
        "description": "突破单一学科限制，将自然、天文、智能等多个大型主题展厅整合于同一场馆体系内，形成综合性的科普辐射圈。",
        "evidence_cases": [
          {
            "case_name": "New Science and Technology Museum of Henan Province",
            "snippet": "整合了科技馆、自然博物馆和天文馆 (integrates the Science Museum, the Nature Museum, and the Astronomy Museum)"
          }
        ],
        "is_general_knowledge": false
      }
    ],
    "innovative_features": [
      "利用中庭墙面与地面延伸出的展厅设计",
      "提供直观导览的视觉线索系统",
      "融合自然景观与休息功能的观景露台",
      "入口处标志性的大型展品陈列（如恐龙骨架）",
      "围绕中庭呈辐射状分布的主题展厅布局"
    ]
  },
  "generated_at": "2025-12-08T02:13:10.458255"
}
